use std::error::Error;
use std::fmt::Write as _;
use std::io::{self, Write};

use wgpu::util::DeviceExt;

const WORKGROUP: u32 = 16;

// One step of the stencil. Reads `src`, writes `dst`; each invocation owns one cell.
// Out-of-grid neighbours are clamped to the edge cell itself.
const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
    _pad0: u32,
    _pad1: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16)
fn step(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= params.width || y >= params.height) {
        return;
    }

    let w = params.width;
    let left = select(x - 1u, x, x == 0u);
    let right = select(x + 1u, x, x == w - 1u);
    let up = select(y - 1u, y, y == 0u);
    let down = select(y + 1u, y, y == params.height - 1u);

    let row = y * w;
    let self_v = src[row + x];
    let left_v = src[row + left];
    let right_v = src[row + right];
    let up_v = src[up * w + x];
    let down_v = src[down * w + x];

    dst[row + x] = (4u * self_v + left_v + right_v + up_v + down_v) / 8u;
}
"#;

struct Input {
    width: u32,
    height: u32,
    steps: u32,
    cells: Vec<u32>,
}

fn parse_input(text: &str) -> Result<Input, Box<dyn Error>> {
    let mut tokens = text.split_ascii_whitespace();
    let mut next = |what: &str| -> Result<u32, Box<dyn Error>> {
        let tok = tokens.next().ok_or_else(|| format!("input ended before {what}"))?;
        Ok(tok.parse::<u32>().map_err(|e| format!("bad {what} '{tok}': {e}"))?)
    };

    let width = next("width")?;
    let height = next("height")?;
    let steps = next("steps")?;
    if !(1..=512).contains(&width) || !(1..=512).contains(&height) {
        return Err(format!("width and height must be 1..=512, got {width}x{height}").into());
    }
    if steps > 1000 {
        return Err(format!("steps must be 0..=1000, got {steps}").into());
    }

    let count = width as usize * height as usize;
    let mut cells = Vec::with_capacity(count);
    for i in 0..count {
        cells.push(next(&format!("cell {i}"))?);
    }
    Ok(Input { width, height, steps, cells })
}

fn run_gpu(input: &Input) -> Result<Vec<u32>, Box<dyn Error>> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        force_fallback_adapter: false,
        compatible_surface: None,
    }))
    .map_err(|e| format!("no GPU adapter available: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| format!("failed to create GPU device: {e}"))?;

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });

    let params = [input.width, input.height, 0u32, 0u32];
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::cast_slice(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });

    let size = (input.cells.len() * std::mem::size_of::<u32>()) as wgpu::BufferAddress;
    let storage_usage = wgpu::BufferUsages::STORAGE
        | wgpu::BufferUsages::COPY_SRC
        | wgpu::BufferUsages::COPY_DST;
    let buf_a = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("grid a"),
        contents: bytemuck::cast_slice(&input.cells),
        usage: storage_usage,
    });
    let buf_b = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("grid b"),
        size,
        usage: storage_usage,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("heat layout"),
        entries: &[
            wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 1,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Storage { read_only: true },
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 2,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Storage { read_only: false },
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
        ],
    });

    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("heat pipeline layout"),
        bind_group_layouts: &[Some(&layout)],
        immediate_size: 0,
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat step"),
        layout: Some(&pipeline_layout),
        module: &module,
        entry_point: Some("step"),
        compilation_options: Default::default(),
        cache: None,
    });

    // Bind group i reads buffer `i` and writes the other one; steps alternate between them.
    let bind = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("heat bind"),
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: params_buf.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: src.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 2, resource: dst.as_entire_binding() },
            ],
        })
    };
    let groups = [bind(&buf_a, &buf_b), bind(&buf_b, &buf_a)];

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("heat steps"),
    });
    let dispatch_x = input.width.div_ceil(WORKGROUP);
    let dispatch_y = input.height.div_ceil(WORKGROUP);
    for step in 0..input.steps {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: Some("heat pass"),
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &groups[(step % 2) as usize], &[]);
        pass.dispatch_workgroups(dispatch_x, dispatch_y, 1);
    }

    // After `steps` writes, the latest values are in buf_b when steps is odd, buf_a otherwise.
    let result_buf = if input.steps % 2 == 1 { &buf_b } else { &buf_a };
    encoder.copy_buffer_to_buffer(result_buf, 0, &readback, 0, size);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |res| {
        let _ = tx.send(res);
    });
    device.poll(wgpu::PollType::wait_indefinitely())?;
    rx.recv()??;

    let data = slice.get_mapped_range();
    let out: Vec<u32> = bytemuck::cast_slice(&data).to_vec();
    drop(data);
    readback.unmap();
    Ok(out)
}

fn main() -> Result<(), Box<dyn Error>> {
    let path = std::env::args()
        .nth(1)
        .ok_or("usage: heat <input-file>")?;
    let text = std::fs::read_to_string(&path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let input = parse_input(&text)?;

    let grid = run_gpu(&input)?;

    let width = input.width as usize;
    let mut out = String::with_capacity(grid.len() * 8);
    let mut sum: u64 = 0;
    for row in grid.chunks(width) {
        for (i, v) in row.iter().enumerate() {
            if i > 0 {
                out.push(' ');
            }
            write!(out, "{v}")?;
            sum += u64::from(*v);
        }
        out.push('\n');
    }
    writeln!(out, "SUM {sum}")?;

    let stdout = io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(out.as_bytes())?;
    lock.flush()?;
    Ok(())
}

